from scipy.ndimage import label

def keypts(a):
    return [(r,c) for r in range(4) for c in range(4) if a[r,c] not in (3,7)]
def transforms(pts):
    res=set()
    for k in range(8):
        out=[]
        for r,c in pts:
            if k<4: x,y=r,c
            else: x,y=r,-c
            for _ in range(k%4): x,y=y,-x
            out.append((x,y))
        mi=min(x for x,y in out); mj=min(y for x,y in out)
        norm=frozenset((x-mi,y-mj) for x,y in out)
        res.add(norm)
    return res
