    pts=set(map(tuple,coords))
    for sh in shape:
        maxr=max(r for r,c in sh); maxc=max(c for r,c in sh)
        for r0,c0 in pts:
            if all((r0+r,c0+c) in pts for r,c in sh):
                pass
        # easier anchors anywhere component coordinate translations
        for r0,c0 in pts:
            if set((r0+r,c0+c) for r,c in sh) <= pts:
                return True
    return False
